extension RegexLiteralLexemes.Element {
  /// The regex literal token kind, the raw value of which indicates its index.
  enum Kind: UInt8 {
    case openingPounds
    case openingSlash
    case pattern
    case closingSlash
    case closingPounds
  }

  /// Retrieve the actual token kind.
  var tokenKind: RawTokenKind {
    switch kind {
    case .openingPounds, .closingPounds:
      return .regexPoundDelimiter
    case .openingSlash, .closingSlash:
      return .regexSlash
    case .pattern:
      return .regexLiteralPattern
    }
  }
}
extension SyntaxKind {
  /// Whether or not this is a literal syntax that doesn't support being followed
  /// by a trailing closure. Array and dictionary literals support trailing closures
  /// since this can mean `[Element].init { }` or `[Key: Value].init { }`.
  fileprivate var isLiteralWithoutTrailingClosureSupport: Bool {
    switch self {
    case .booleanLiteralExpr, .floatLiteralExpr, .integerLiteralExpr, .nilLiteralExpr,
      .regexLiteralExpr, .stringLiteralExpr:
      return true
    default:
      return false
    }
  }
}
}

